/*
 * Starter 5: Soundboard
 *
 * Press A, S, or D to play a musical note. Each note has a colored pad on
 * screen that lights up while its sound is playing.
 *
 * The notes are generated by the program itself (see `makeTone` below), so
 * you don't need any sound files. If you'd like, you can load a .wav or .ogg
 * file instead -- see the SFML audio tutorial.
 *
 * Your two TODOs:
 *   TODO 1: Add a fourth note that plays when you press F.
 *   TODO 2: Make the Up/Down arrow keys turn the volume of every note up/down.
 *
 * Compile (note the extra -lsfml-audio; you may need extra flags for your
 * setup, as in Step 1):
 *   g++ -std=c++20 main.cpp -o main -lsfml-audio -lsfml-graphics -lsfml-window -lsfml-system
 */

#include <SFML/Audio.hpp>
#include <SFML/Graphics.hpp>
#include <cmath>
#include <cstdint>
#include <vector>

/*
 * Builds a sf::SoundBuffer containing half a second of a pure tone at the
 * given frequency (in Hz). You don't need to change or understand this
 * function to complete the TODOs, but here is the idea: sound is a list of
 * "samples" (numbers between -32768 and 32767) describing how a speaker
 * should move over time. A sine wave that repeats `frequency` times per
 * second sounds like a musical note.
 */
sf::SoundBuffer makeTone(float frequency) {
    const unsigned int sampleRate = 44100;  // samples per second
    const float duration = 0.5f;            // seconds
    const auto sampleCount = static_cast<std::size_t>(sampleRate * duration);
    const float pi = 3.14159265f;

    std::vector<std::int16_t> samples(sampleCount);
    for (std::size_t i = 0; i < sampleCount; i++) {
        float t = static_cast<float>(i) / sampleRate;
        float fade = 1.f - static_cast<float>(i) / sampleCount;  // fade out to avoid a "click"
        samples[i] = static_cast<std::int16_t>(12000 * fade * std::sin(2 * pi * frequency * t));
    }

    return sf::SoundBuffer(samples.data(), samples.size(), 1, sampleRate, {sf::SoundChannel::Mono});
}

/* Creates a colored square "pad" at the given x coordinate. */
sf::RectangleShape makePad(float x, sf::Color color) {
    sf::RectangleShape pad({150.f, 150.f});
    pad.setPosition({x, 175.f});
    pad.setFillColor(color);
    return pad;
}

int main() {
    sf::RenderWindow window(sf::VideoMode({800, 500}), "Soundboard");
    window.setFramerateLimit(60);

    // A sf::SoundBuffer holds audio data. A sf::Sound plays a buffer.
    // (The buffer must stay alive as long as the sound that uses it.)
    sf::SoundBuffer bufferC = makeTone(261.63f);  // the note C
    sf::SoundBuffer bufferE = makeTone(329.63f);  // the note E
    sf::SoundBuffer bufferG = makeTone(392.00f);  // the note G

    sf::Sound soundC(bufferC);
    sf::Sound soundE(bufferE);
    sf::Sound soundG(bufferG);

    // One pad per note, so you can see which note is playing.
    sf::RectangleShape padC = makePad(25.f, sf::Color(230, 80, 80));
    sf::RectangleShape padE = makePad(225.f, sf::Color(80, 200, 120));
    sf::RectangleShape padG = makePad(425.f, sf::Color(80, 140, 230));

    // TODO 1 (part a): Create a fourth note. Make a new buffer with
    // makeTone (try 440.0 Hz, the note A) and a new sf::Sound that plays it.
    // A fourth pad at x = 625 is optional but nice.

    while (window.isOpen()) {
        while (const std::optional event = window.pollEvent()) {
            if (event->is<sf::Event::Closed>()) {
                window.close();
            } else if (const auto* key = event->getIf<sf::Event::KeyPressed>()) {
                if (key->scancode == sf::Keyboard::Scancode::A) {
                    soundC.play();
                } else if (key->scancode == sf::Keyboard::Scancode::S) {
                    soundE.play();
                } else if (key->scancode == sf::Keyboard::Scancode::D) {
                    soundG.play();
                }

                // TODO 1 (part b): Play your new note when F is pressed.
                //   Done when: pressing F plays a note you haven't heard yet.

                // TODO 2: When Up is pressed, make every note louder; when
                // Down is pressed, make every note quieter. (A sound's volume
                // ranges from 0 to 100 and starts at 100, so you may want to
                // turn it down first to hear it go up.)
                //   Done when: after pressing Down a few times, the notes are
                //   noticeably quieter, and pressing Up makes them louder again.
            }
        }

        // A pad is drawn brightly while its sound is playing, and dimmed
        // (mostly transparent) otherwise.
        auto drawPad = [&window](sf::RectangleShape& pad, const sf::Sound& sound) {
            sf::Color color = pad.getFillColor();
            color.a = (sound.getStatus() == sf::Sound::Status::Playing) ? 255 : 70;
            pad.setFillColor(color);
            window.draw(pad);
        };

        window.clear(sf::Color(25, 25, 25));
        drawPad(padC, soundC);
        drawPad(padE, soundE);
        drawPad(padG, soundG);
        window.display();
    }

    return 0;
}
